def anti_shuffle(s):
    words = s.split(' ')
    sorted_words = []

    for word in words:
        sorted_word = ''.join(sorted(word))
        sorted_words.append(sorted_word)

    result = ' '.join(sorted_words)

    # Maintain the spaces in the original sentence
    original_spaces = []
    for char in s:
        if char == ' ':
            original_spaces.append(' ')

    # Rebuild the result to maintain original spacing
    final_result = []
    result_index = 0

    for char in s:
        if char == ' ':
            final_result.append(' ')
        else:
            final_result.append(result[result_index])
            result_index += 1

    return ''.join(final_result)

